import sys

def main():
    data = sys.stdin.read().split()
    t = int(data[0])
    out = []
    for i in range(1, t + 1):
        n = int(data[i])
        if n % 2 == 0 or n < 3:
            out.append(-1)
        else:
            out.append((n // 2) * (n // 2 + 1))
    print('\n'.join(map(str, out)))

main()

